import { Fragment, useEffect, useRef, useState, type CSSProperties, type PointerEvent as ReactPointerEvent } from 'react';
import { Activity, CalendarDays, Check, ChevronDown, ChevronLeft, ChevronRight, Clock3, FileBarChart2, FolderKanban, ListTodo, Map, MoreHorizontal, PanelLeftClose, PanelLeftOpen, Pause, Play, Plus, Search, Settings2, Square, StickyNote, Target, Trash2, FolderOpen, X, ZoomIn, ZoomOut, Maximize2 } from 'lucide-react';
