  const monthFirst=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth(),1); const monthOffset=(monthFirst.getDay()+(store.settings.weekStart==='Monday'?6:0))%7; const monthDays=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+1,0).getDate(); const calendarCells=[...Array(monthOffset).fill(null),...Array.from({length:monthDays},(_,i)=>i+1)];
  const selectedDaySessions=store.sessions.filter(x=>durationOnDay(x.start,x.end??now,calendarSelectedDate)>0); const selectedDayEvents=store.calendarEvents.filter(event=>event.date===calendarSelectedDate); const selectedDayMs=selectedDaySessions.reduce((sum,x)=>sum+durationOnDay(x.start,x.end??now,calendarSelectedDate),0);
  const reportSessions=store.sessions.filter(s=>durationOnDay(s.start,s.end??now,reportDate)>0); const reportEntries=store.tasks.filter(task=>task.kind!=='project').flatMap(task=>task.entries.map(entry=>({task,entry,duration:durationOnDay(entry.start,entry.end??now,reportDate)}))).filter(x=>x.duration>0); const reportTaskGroups=store.tasks.map(task=>({task,entries:reportEntries.filter(x=>x.task.id===task.id)})).filter(x=>x.entries.length>0); const reportWorkMs=reportSessions.reduce((sum,s)=>sum+durationOnDay(s.start,s.end??now,reportDate),0); const reportAllocationMs=reportEntries.reduce((sum,x)=>sum+x.duration,0);
  function startDay() { setStore(s=>{if(activeSession(s))return s;const stamp=Date.now(),session={id:uid(),start:stamp};const resume=s.tasks.find(t=>t.id===s.resumeTaskId&&!t.done&&t.kind!=='project');return {...s,sessions:[...s.sessions,session],tasks:s.tasks.map(t=>t.id===resume?.id?{...t,entries:[...t.entries,{id:uid(),start:stamp,sessionId:session.id}]}:t),activeTaskId:resume?.id,resumeTaskId:undefined};}); }
  function pauseDay(endDay = false) { const current = activeSession(store); if (!current) return; const stamp = Date.now(); setStore(s => ({...s, sessions:s.sessions.map(x => x.id === current.id ? {...x,end:stamp} : x), tasks:s.tasks.map(t => t.id === s.activeTaskId ? {...t,entries:t.entries.map(e => !e.end ? {...e,end:stamp} : e)} : t), resumeTaskId:endDay?undefined:s.activeTaskId, activeTaskId:undefined})); }
  function openAddTask(parentId?: string, kind:'project'|'task'='task') { setAddParentId(parentId); setNewName(''); setNewDescription(''); setNewKind(parentId?'task':kind); setNewPriority('medium');setNewImportance('medium');setNewPlannedDate(''); const category=store.settings.categories[0]; setNewCategory(category?.name??''); setNewProjectColor(parentId?(inheritedColor(parentId,store.tasks)??category?.color??'#7664c8'):kind==='project'?'#7664c8':(category?.color??'#7664c8')); setNewColorTouched(false); setAdding(true); }
  function addTask() { const name = newName.trim(); if (!name) return; const id=uid(); const kind=addParentId?'task':newKind; const category=store.settings.categories.find(c=>c.name===newCategory); setStore(s => ({...s,tasks:[...s.tasks,{id,name,description:newDescription.trim(),parentId:addParentId,kind,category:newCategory,categoryColor:category?.color,projectColor:kind==='project'||newColorTouched?newProjectColor:undefined,priority:kind==='project'?undefined:newPriority,importance:kind==='project'?undefined:newImportance,plannedDate:kind==='project'?undefined:newPlannedDate||undefined,createdAt:Date.now(),notesColor:'yellow',dependencies:[],done:false,entries:[]}]})); if(page==='Mind map') setMapToTaskTree(addParentId ?? id); setNewName('');setNewDescription('');setAdding(false); }
  function updateSettings(patch:Partial<Store['settings']>) { setStore(s=>({...s,settings:{...s.settings,...patch}})); }
